import{z as o,x as s,o as e,c as B,q as l,j as A,D as E,d as r,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"落后者缓解","description":"","frontmatter":{"title":"落后者缓解","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/straggler-mitigation.md","filePath":"llm/straggler-mitigation.md","lastUpdated":1791413859000}'),p={name:"llm/straggler-mitigation.md"};function d(m,a,_,h,D,c){const t=s("Mermaid");return e(),B("div",null,[a[2]||(a[2]=l('<h1 id="落后者缓解" tabindex="-1">落后者缓解 <a class="header-anchor" href="#落后者缓解" aria-label="Permalink to &quot;落后者缓解&quot;">​</a></h1><div class="epigraph"><p>同步迭代的时间等于最慢那张卡；热专家、坏 GPU、抖动的数据加载，都会让其余千卡陪着等。</p><footer>—— 据 Dean 等对同步系统落后者的经典观察；Jiang 等 MegaScale 的大集群训练实践</footer></div><p><a href="/llm/elastic-training">上一课</a>处理已经死掉的 rank。更常见的是：心跳还在，集合通信每次都最后完成。本课不重讲世界缩小。缺口是识别与缓解落后者——热 MoE 专家、SP 组里的慢注意力、磁盘偶发、时钟降频——以及哪些手段会破坏训练重放。训练重放需要确定性；本课的缓解若包含「丢弃慢微批」，就必须声明对梯度的影响。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1F1B、All-Reduce、All-to-All、Ulysses 置换全是栅栏。分布的尾延迟决定步时。MegaScale 在万卡上把落后者当成一等故障：不杀进程也要把尾部剪掉或隔离。来源分三类。计算：路由把 token 堆到少数专家，或某卡降频。通信：拓扑不对称，某跨架链路拥塞。数据：某个 rank 的加载器在解压超大文档。数据课的长文档上采样若没做长度分桶，会系统性制造数据落后者。</p><p><span class="marginnote">直觉类比：同步训练像一群人绑腿赛跑，队伍速度等于最慢那条腿。热专家、降频的 GPU、慢磁盘都是那条「慢腿」；优化全队平均体能（平均 MFU）没有用，要么帮慢腿减负，要么把它换下来。</span></p><p>误杀的代价是弹性风暴。缓解应先分级：观测 → 迁移负载 → 换节点，而不是第一步就 shrink 世界。</p><h3 id="moe-热专家是结构性落后者" tabindex="-1">MoE 热专家是结构性落后者 <a class="header-anchor" href="#moe-热专家是结构性落后者" aria-label="Permalink to &quot;MoE 热专家是结构性落后者&quot;">​</a></h3><p>负载均衡失败时，落后者每周出现。应先把辅助损失或偏置调到容量曲线平坦，再谈硬件。把结构性问题当坏卡，会永远换到下一张仍热的卡。</p><p><span class="marginnote">profiler 只看均值会看不见尾部。应报每 rank 步时的 P99，以及 All-to-All 等待分解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每步记录各 rank 在各栅栏上的等待时间。超过阈值：先把该 rank 的数据管道与计算分开看（加载器队列是否空）。数据问题：预取加深、把超长样本改到专用微批、或对该文档切片。计算问题：查 GPU 错误计数、功耗、是否与检查点 writer 抢拷贝。通信问题：对照拓扑放置是否把 TP/EP 跨到了弱链路。</p><p>缓解手段按侵入性排序：绑核与 NUMA、隔离异步保存到少数 rank、动态把热专家副本增加（若框架支持）、把该节点标脏并在下一检查点弹性换出。不要在步内丢弃未完成的微批充数，除非实验明确接受有偏梯度。</p>',13)),(e(),A(n,null,{default:E(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DET%5B%22%E6%9F%90%20rank%20%E6%A0%85%E6%A0%8F%E7%AD%89%E5%BE%85%E8%B6%85%E9%98%88%E5%80%BC%22%5D%20--%3E%20CLASS%5B%22%E5%85%88%E5%88%86%E7%B1%BB%3A%20%E6%95%B0%E6%8D%AE%20%2F%20%E8%AE%A1%E7%AE%97%20%2F%20%E9%80%9A%E4%BF%A1%20%2F%20%E7%83%AD%E4%B8%93%E5%AE%B6%22%5D%0A%20%20CLASS%20--%3E%20L1%5B%22%E8%BD%BB%3A%20%E7%BB%91%E6%A0%B8%E4%B8%8E%20NUMA%2C%20%E5%8A%A0%E6%B7%B1%E9%A2%84%E5%8F%96%22%5D%0A%20%20CLASS%20--%3E%20L2%5B%22%E4%B8%AD%3A%20%E9%9A%94%E7%A6%BB%E5%BC%82%E6%AD%A5%E4%BF%9D%E5%AD%98%2C%20%E5%8A%A0%E7%83%AD%E4%B8%93%E5%AE%B6%E5%89%AF%E6%9C%AC%22%5D%0A%20%20CLASS%20--%3E%20L3%5B%22%E9%87%8D%3A%20%E6%A0%87%E8%84%8F%E8%8A%82%E7%82%B9%2C%20%E4%B8%8B%E4%B8%AA%E6%A3%80%E6%9F%A5%E7%82%B9%E5%BC%B9%E6%80%A7%E6%8D%A2%E5%87%BA%22%5D%0A%20%20L3%20--%3E%20NO%5B%22%E7%A6%81%3A%20%E6%AD%A5%E5%86%85%E4%B8%A2%E5%BE%AE%E6%89%B9%E5%85%85%E6%95%B0%2C%20%E4%BC%9A%E5%81%8F%E6%A2%AF%E5%BA%A6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h3 id="与重叠的关系" tabindex="-1">与重叠的关系 <a class="header-anchor" href="#与重叠的关系" aria-label="Permalink to &quot;与重叠的关系&quot;">​</a></h3><p>重叠把均值变好看，尾部仍在 wait。落后者会使「通信暴露时间」在单 rank 爆炸，其余 rank 的重叠窗口空转。治理落后者往往比再调一版 DualPipe 更赚。</p><p><span class="marginnote">训练中评测若打在同步路径上（每个 n 步全员等评测），评测机会成为周期性落后者。应异步、降频、或只用子集 rank。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同步 SGD 的一步是 \\(\\max_i T_i\\)。优化均值 \\(T\\) 而不优化 \\(\\max\\)，集群越大越亏。这与数据并行线性加速的假设相反：加速比被尾部卡住。弹性处理的是 \\(T_i=\\infty\\)；本课处理 \\(T_i\\) 处于分布右尾。</p><p><span class="marginnote">数字实例：1000 卡集群每步本应 1 秒，若 1 张卡每步慢 0.1 秒，其余 999 卡每步都得白等 0.1 秒——总吞吐损失约 9%，而各 rank 的平均耗时只比理想值高 0.01%。均值几乎看不见，P99 一眼暴露：这就是看 P99 不看均值的算术理由。</span></p>',6)),(e(),A(n,null,{default:E(()=>[i(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20BAR%5B%22%E9%9B%86%E5%90%88%E9%80%9A%E4%BF%A1%E6%A0%85%E6%A0%8F%22%5D%20--%3E%20WAIT%5B%22%E6%AF%8F%20rank%20%E7%AD%89%E5%BE%85%E5%88%86%E8%A7%A3%22%5D%0A%20%20WAIT%20--%3E%20DAT%5B%22%E6%95%B0%E6%8D%AE%E7%AE%A1%E9%81%93%3F%22%5D%0A%20%20WAIT%20--%3E%20CMP%5B%22%E8%AE%A1%E7%AE%97%20%2F%20%E9%99%8D%E9%A2%91%3F%22%5D%0A%20%20WAIT%20--%3E%20NET%5B%22%E6%8B%93%E6%89%91%E6%8B%A5%E5%A1%9E%3F%22%5D%0A%20%20WAIT%20--%3E%20MOE%5B%22%E7%83%AD%E4%B8%93%E5%AE%B6%3F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>缓解不能承诺消除物理故障，只降低活着的尾延迟。确定性重放要求：不能把「随机跳过慢 batch」当作默认。下一课规定如何在需要时重跑同一串微批，以区分软件 bug 与真正的坏硬件。</p><p><span class="marginnote">常见误区：一看到慢卡就把它踢出集群。若慢的根源是 MoE 负载不均，热点只会转移到别的卡上——换卡永远换不完。结构性问题（路由堆 token）要先调均衡，硬件问题（坏卡、降频）才轮到换节点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲掉卡拉起；只补活着的尾延迟。</li><li>先分解等待：数据、计算、网络、MoE 负载。</li><li>侵入性从小到大；步内丢微批会偏梯度。</li><li>P99 与栅栏分解比平均 MFU 更有用。</li><li>出处：Jiang et al., MegaScale, 2024；Dean 等对同步落后者的讨论；对照 MoE 负载均衡。</li></ul>',5))])}const g=o(p,[["render",d]]);export{u as __pageData,g as default};
